	// HasScheduledPost applies the HasEdge predicate on the "scheduled_post" edge.
	func HasScheduledPost() predicate.PublicationAttempt {
		return predicate.PublicationAttempt(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
				sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ScheduledPostTable,ScheduledPostColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
	}
	
	// HasScheduledPostWith applies the HasEdge predicate on the "scheduled_post" edge with a given conditions (other predicates).
	func HasScheduledPostWith(preds ...predicate.ScheduledPost) predicate.PublicationAttempt {
		return predicate.PublicationAttempt(func(s *sql.Selector) {
		step := newScheduledPostStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
	}


// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PublicationAttempt) predicate.PublicationAttempt {
	return predicate.PublicationAttempt(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PublicationAttempt) predicate.PublicationAttempt {
	return predicate.PublicationAttempt(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PublicationAttempt) predicate.PublicationAttempt {
	return predicate.PublicationAttempt(sql.NotPredicates(p))
}





